const cloneCase = (caseData) => JSON.parse(JSON.stringify(caseData));

function combinations(items, size, start = 0, current = [], output = []) {
  if (current.length === size) {
    output.push([...current]);
    return output;
  }
  for (let index = start; index <= items.length - (size - current.length); index += 1) {
    current.push(items[index]);
    combinations(items, size, index + 1, current, output);
    current.pop();
  }
  return output;
}

const inheritedAmount = (result, targetId) =>
  result.heirs.find((heir) => heir.personId === targetId)?.amount || 0;

function solveForTarget(caseData, lawPack, targetId, targetAmount, options = {}) {
  const goal = Number(targetAmount);
  const target = caseData.people.find((person) => person.id === targetId);
  const currentResult = calculateInheritance(caseData, lawPack);
  const currentAmount = inheritedAmount(currentResult, targetId);

  if (!target || target.status !== 'alive' || !Number.isFinite(goal) || goal < 0) {
    return { currentAmount, goal, solutions: [], error: '请选择生存的目标人物，并输入有效金额。' };
  }
  if (currentAmount >= goal) {
    return { currentAmount, goal, solutions: [], reached: true };
  }

  const allCandidates = caseData.people.filter((person) => person.id !== targetId && person.status === 'alive');
  const candidateLimit = options.candidateLimit || 14;
  const candidates = allCandidates.slice(0, candidateLimit);
  const maxChanges = Math.min(candidates.length, options.maxChanges || (candidates.length <= 12 ? candidates.length : 5));
  const solutionLimit = options.solutionLimit || 3;
  let bestAmount = currentAmount;
  let examined = 0;

  for (let size = 1; size <= maxChanges; size += 1) {
    const found = [];
    for (const selected of combinations(candidates, size)) {
      const scenario = cloneCase(caseData);
      const selectedIds = new Set(selected.map((person) => person.id));
      scenario.people.forEach((person) => {
        if (selectedIds.has(person.id)) person.status = 'predeceased';
      });
      const result = calculateInheritance(scenario, lawPack);
      const amount = inheritedAmount(result, targetId);
      bestAmount = Math.max(bestAmount, amount);
      examined += 1;
      if (amount >= goal) {
        found.push({
          amount,
          changes: selected.map((person) => ({
            personId: person.id,
            name: person.name,
            from: 'alive',
            to: 'predeceased'
          }))
        });
      }
    }
    if (found.length) {
      found.sort((left, right) => left.amount - right.amount || left.changes.map((item) => item.name).join('').localeCompare(right.changes.map((item) => item.name).join(''), 'zh-CN'));
      return {
        currentAmount,
        goal,
        solutions: found.slice(0, solutionLimit),
        examined,
        truncated: allCandidates.length > candidates.length
      };
    }
  }

  return {
    currentAmount,
    goal,
    solutions: [],
    bestAmount,
    examined,
    truncated: allCandidates.length > candidates.length || maxChanges < candidates.length
  };
}



const cloneStormCase = (caseData) => JSON.parse(JSON.stringify(caseData));
const amountMap = (result) => new Map(result.heirs.map((heir) => [heir.personId, heir.amount]));

const eventStatuses = {
  death: 'predeceased',
  disqualified: 'disqualified',
  renounced: 'renounced'
};

function analyzeEventSequence(caseData, lawPack, events) {
  const scenario = cloneStormCase(caseData);
  const baseline = calculateInheritance(scenario, lawPack);
  let previousAmounts = amountMap(baseline);
  const benefitScores = new Map(caseData.people.map((person) => [person.id, 0]));
  const timeline = [];

  events.forEach((event, index) => {
    const person = scenario.people.find((candidate) => candidate.id === event.personId);
    if (!person || !eventStatuses[event.type]) return;
    person.status = eventStatuses[event.type];
    const result = calculateInheritance(scenario, lawPack);
    const currentAmounts = amountMap(result);
    const changes = scenario.people
      .map((candidate) => {
        const before = previousAmounts.get(candidate.id) || 0;
        const after = currentAmounts.get(candidate.id) || 0;
        return { personId: candidate.id, name: candidate.name, before, after, delta: after - before };
      })
      .filter((change) => Math.abs(change.delta) > 0.000001)
      .sort((left, right) => right.delta - left.delta);

    changes.forEach((change) => {
      if (change.delta > 0) benefitScores.set(change.personId, (benefitScores.get(change.personId) || 0) + change.delta);
    });
    timeline.push({
      index: index + 1,
      event,
      personName: person.name,
      status: person.status,
      changes,
      result
    });
    previousAmounts = currentAmounts;
  });

  const finalResult = timeline.at(-1)?.result || baseline;
  const finalAmounts = amountMap(finalResult);
  const finalPeople = scenario.people.filter((person) => person.status === 'alive');
  let weights = finalPeople.map((person) => ({
    personId: person.id,
    name: person.name,
    amount: finalAmounts.get(person.id) || 0,
    score: benefitScores.get(person.id) || 0
  }));
  let totalScore = weights.reduce((sum, person) => sum + person.score, 0);

  if (totalScore <= 0) {
    weights = weights.map((person) => ({ ...person, score: person.amount }));
    totalScore = weights.reduce((sum, person) => sum + person.score, 0);
  }

  const ranking = weights
    .filter((person) => person.score > 0)
    .map((person) => ({ ...person, probability: totalScore ? person.score / totalScore * 100 : 0 }))
    .sort((left, right) => right.probability - left.probability || right.amount - left.amount || left.name.localeCompare(right.name, 'zh-CN'));

  return { baseline, finalResult, timeline, ranking };
}



